[{"type": "legacy_vis", "embeddableConfig": {"savedVis": {"title": "Active P1 / P2 / P3", "description": "", "type": "vega", "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "padding": 8,
  "data": [
    {
      "name": "raw",
      "url": {
        "%type%": "esql",
        "query": "FROM servicenow-incidents-*\n| WHERE @timestamp >= NOW() - 1 month\n| EVAL inc = TO_STRING(number), pri_n = TO_INTEGER(priority), state = TO_STRING(state_name)\n| WHERE inc LIKE \"INC*\" AND pri_n IN (1, 2, 3) AND state NOT IN (\"Resolved\", \"Closed\", \"Canceled\", \"Cancelled\")\n| STATS pri = MIN(pri_n) BY inc\n| EVAL label = CASE(pri == 1, \"P1\", pri == 2, \"P2\", \"P3\")\n| STATS incidents = COUNT(*) BY label\n| SORT label ASC"
      }
    },
    {
      "name": "prios",
      "values": [
        {
          "label": "P1"
        },
        {
          "label": "P2"
        },
        {
          "label": "P3"
        }
      ],
      "transform": [
        {
          "type": "lookup",
          "from": "raw",
          "key": "label",
          "fields": [
            "label"
          ],
          "values": [
            "incidents"
          ],
          "as": [
            "incidents"
          ],
          "default": 0
        }
      ]
    },
    {
      "name": "slices",
      "source": "prios",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.incidents > 0"
        },
        {
          "type": "joinaggregate",
          "fields": [
            "incidents"
          ],
          "ops": [
            "sum"
          ],
          "as": [
            "all"
          ]
        },
        {
          "type": "formula",
          "as": "weight",
          "expr": "max(datum.incidents, datum.all * 0.06)"
        },
        {
          "type": "pie",
          "field": "weight",
          "sort": false
        }
      ]
    },
    {
      "name": "total",
      "source": "prios",
      "transform": [
        {
          "type": "aggregate",
          "fields": [
            "incidents"
          ],
          "ops": [
            "sum"
          ],
          "as": [
            "n"
          ]
        }
      ]
    }
  ],
  "signals": [
    {
      "name": "r",
      "update": "min(width * 0.6, height) / 2"
    }
  ],
  "scales": [
    {
      "name": "colour",
      "type": "ordinal",
      "domain": [
        "P1",
        "P2",
        "P3"
      ],
      "range": [
        "#d6453d",
        "#c98a0b",
        "#3f6fb5"
      ]
    }
  ],
  "marks": [
    {
      "type": "arc",
      "from": {
        "data": "slices"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "r + 4"
          },
          "y": {
            "signal": "height / 2"
          },
          "startAngle": {
            "field": "startAngle"
          },
          "endAngle": {
            "field": "endAngle"
          },
          "innerRadius": {
            "signal": "r * 0.58"
          },
          "outerRadius": {
            "signal": "r"
          },
          "padAngle": {
            "value": 0.02
          },
          "fill": {
            "scale": "colour",
            "field": "label"
          },
          "tooltip": {
            "signal": "{'Priority': datum.label, 'Active incidents': datum.incidents}"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "total"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "r + 4"
          },
          "y": {
            "signal": "height / 2 - 4"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "middle"
          },
          "text": {
            "signal": "datum.n"
          },
          "fontSize": {
            "signal": "max(r * 0.42, 14)"
          },
          "fontWeight": {
            "value": "bold"
          }
        }
      },
      "style": "guide-title"
    },
    {
      "type": "text",
      "encode": {
        "update": {
          "x": {
            "signal": "r + 4"
          },
          "y": {
            "signal": "height / 2 + r * 0.28"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "middle"
          },
          "text": {
            "value": "active"
          },
          "fontSize": {
            "value": 12
          }
        }
      },
      "style": "guide-label"
    },
    {
      "type": "text",
      "from": {
        "data": "prios"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "2 * r + 24"
          },
          "y": {
            "signal": "height / 2 + (datum.label == 'P1' ? -34 : datum.label == 'P2' ? 0 : 34)"
          },
          "baseline": {
            "value": "middle"
          },
          "text": {
            "signal": "datum.label + '  ' + datum.incidents"
          },
          "fontSize": {
            "value": 24
          },
          "fontWeight": {
            "value": "bold"
          },
          "fill": {
            "scale": "colour",
            "field": "label"
          },
          "opacity": {
            "signal": "datum.incidents > 0 ? 1 : 0.4"
          }
        }
      }
    }
  ]
}"}, "uiState": {}, "data": {"aggs": [], "searchSource": {"query": {"query": "", "language": "kuery"}, "filter": []}}}, "title": "Active P1 / P2 / P3", "description": "How many P1 (red), P2 (amber) and P3 (blue) incidents are active now (priority 1, 2 or 3, state not Resolved, Closed, Canceled or Cancelled), with the total in the middle. Last 1 month (fixed, the same as Active Incidents, so both count the same incidents whatever the time picker says); not narrowed by the Incident or CI controls. Every priority with an active incident gets a visible slice (at least 6 % of the ring, so a single P2 next to hundreds of P3s still shows); the numbers beside the ring are the real counts.", "time_range": {"from": "now-1M", "to": "now"}}, "panelIndex": "51da697e-ae2f-57b0-93a9-2f3ce02b3837", "gridData": {"y": 0, "x": 0, "w": 14, "h": 10, "i": "51da697e-ae2f-57b0-93a9-2f3ce02b3837", "sectionId": "37e9584c-0ce2-5010-b5d5-6c3b9efa7fff"}}, {"type": "legacy_vis", "embeddableConfig": {"savedVis": {"title": "User base · ServiceNow", "description": "", "type": "vega", "params": {"spec": "{
